  var c = [1, 2, 3, 4, 5, 6, 7].map(function (i) { return o.contenuLg(b[i] && b[i].contenu, lg); });
  var tailles = [5, 5, 8, 8, 6, 6, 6];
  var valide = c.every(function (x, i) { return x.length === tailles[i]; }) && (cours.quiz || []).length === 10;
